<?php require __DIR__.'/bootstrap.php';require __DIR__.'/smtp.php';if(!empty($_SESSION['uid']))go();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';
if($action==='send'){$email=strtolower(trim((string)($_POST['email']??'')));$u=q('SELECT * FROM mn_users WHERE email=? AND enabled=1',[$email])->fetch();$message='If this email is authorized, a six-digit code has been sent.';
if($u){$old=q('SELECT * FROM mn_codes WHERE user_id=?',[$u['id']])->fetch();$now=time();$recent=$old&&strtotime($old['window_at'])>$now-3600;$count=$recent?(int)$old['sends']:0;if((!$old||strtotime($old['sent_at'])<=$now-60)&&$count<5){$code=(string)random_int(100000,999999);$hash=password_hash($code,PASSWORD_DEFAULT);$minutes=max(2,min(30,(int)setting('code_minutes','10')));$sender=setting('mail_from',MN_MAIL_FROM);$headers=['Content-Type: text/plain; charset=UTF-8'];if(filter_var($sender,FILTER_VALIDATE_EMAIL))$headers[]='From: '.str_replace(["\r","\n"],'',$sender);if(mynotes_send_code($email,$code,$minutes)){q('INSERT INTO mn_codes(user_id,code_hash,expires_at,attempts,sent_at,window_at,sends) VALUES(?,?,DATE_ADD(NOW(),INTERVAL '.$minutes.' MINUTE),0,NOW(),NOW(),1) ON DUPLICATE KEY UPDATE code_hash=VALUES(code_hash),expires_at=VALUES(expires_at),attempts=0,sent_at=NOW(),window_at=IF(window_at<DATE_SUB(NOW(),INTERVAL 1 HOUR),NOW(),window_at),sends=IF(window_at<DATE_SUB(NOW(),INTERVAL 1 HOUR),1,sends+1)',[$u['id'],$hash]);$_SESSION['pending_user']=(int)$u['id'];}else{error_log('MyNotes mail delivery failed');}}}}
if($action==='verify'){$id=(int)($_SESSION['pending_user']??0);$code=trim((string)($_POST['code']??''));$r=$id?q('SELECT c.*,u.enabled,u.is_admin,(c.expires_at <= NOW()) AS is_expired FROM mn_codes c JOIN mn_users u ON u.id=c.user_id WHERE c.user_id=?',[$id])->fetch():false;if($r&&$r['enabled']&&preg_match('/^[0-9]{6}$/D',$code)&&!(int)$r['is_expired']&&(int)$r['attempts']<5){q('UPDATE mn_codes SET attempts=attempts+1 WHERE user_id=?',[$id]);if(password_verify($code,$r['code_hash'])){q('DELETE FROM mn_codes WHERE user_id=?',[$id]);session_regenerate_id(true);$_SESSION['uid']=$id;$_SESSION['admin']=(bool)$r['is_admin'];$_SESSION['last_active']=time();unset($_SESSION['pending_user']);go();}}$error='Invalid or expired code. Please request another.';}}
?><!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MyNotes · Sign in</title><link rel="stylesheet" href="style.css"><main class="login"><h1>My<span>Notes</span></h1><p>Private notes. Sign in with an approved email.</p><?php if($message):?><p class="notice"><?=h($message)?></p><?php endif;?><?php if($error):?><p class="error"><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="send"><label>Email address</label><input type="email" name="email" autocomplete="email" required><button>Send six-digit code</button></form><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="verify"><label>Six-digit code</label><input name="code" pattern="[0-9]{6}" maxlength="6" inputmode="numeric" autocomplete="one-time-code" required><button>Sign in</button></form></main></html>
